import { Dialog, DialogContent, DialogTitle, IconButton } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import BlocksText from "../components/BlocksText";
import type { BlocksContent } from "../types/home";

const HEADING = "#2E74B5";

type PlanLearnMoreModalProps = {
  open: boolean;
  title?: string;
  content?: BlocksContent;
  onClose: () => void;
};

export default function PlanLearnMoreModal({
  open,
  title,
  content,
  onClose,
}: PlanLearnMoreModalProps) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      scroll="paper"
      aria-labelledby="plan-learn-more-title"
    >
      <DialogTitle
        id="plan-learn-more-title"
        sx={{
          fontWeight: 700,
          fontSize: { xs: 18, md: 22 },
          pr: 6,
          color: "#17224d",
        }}
      >
        {title}
        <IconButton
          onClick={onClose}
          aria-label="Close"
          sx={{ position: "absolute", right: 8, top: 8 }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent dividers sx={{ minHeight: 300, py: 3 }}>
        <BlocksText
          content={content}
          sx={{
            color: "#333",
            fontSize: 16,
            lineHeight: 1.7,
            "& h3": {
              color: HEADING,
              fontSize: { xs: 22, md: 28 },
              fontWeight: 700,
              mt: 0,
              mb: 1.5,
            },
            "& h4, & h5": {
              color: HEADING,
              fontSize: { xs: 18, md: 22 },
              fontWeight: 700,
              mt: 3,
              mb: 1.5,
              pt: 2,
              borderTop: "2px solid #2E74B5",
            },
            "& p": {
              fontSize: 16,
              lineHeight: 1.7,
              mb: 1.5,
            },
            "& strong": {
              fontWeight: 700,
            },
            "& ul, & ol": {
              pl: 2.5,
              mb: 2,
            },
            "& li": {
              fontSize: 15,
              lineHeight: 1.6,
              mb: 1,
            },
          }}
        />
      </DialogContent>
    </Dialog>
  );
}
